package com.arena.core.training;
import jakarta.validation.Valid;
import jakarta.validation.constraints.*;
import lombok.RequiredArgsConstructor;
import org.springframework.web.bind.annotation.*;
import org.springframework.security.core.annotation.AuthenticationPrincipal;
import org.springframework.security.oauth2.jwt.Jwt;
import java.util.Set;
@io.swagger.v3.oas.annotations.tags.Tag(name="Staff login access")
@RestController @RequestMapping("/api/academy/staff/{id}/login") @RequiredArgsConstructor
public class StaffLoginController {
 private final StaffLoginService login;
 public record Roles(@NotNull Long version,@NotEmpty Set<@Pattern(regexp="MANAGER|INSTRUCTOR|STAFF") String> roles){}
 public record ManagerAccess(@NotNull Long version,@NotNull @Pattern(regexp="STANDARD|FULL_OPERATIONS") String accessLevel){}
 @io.swagger.v3.oas.annotations.Operation(summary="Update Manager access level (Owner only)", description="Owner-only operation; current academy and record version required. Managers cannot manage Owners/Managers or grant MANAGER. Login is optional and separate from personnel registration. Setup uses Keycloak VERIFY_EMAIL, UPDATE_PASSWORD and one-time ARENA_STAFF_SETUP; password/verification actions run in Keycloak, not new ArenaOps endpoints.")
 @com.arena.core.documentation.DocumentedErrors({com.arena.core.exception.ErrorCode.CONFLICT,com.arena.core.exception.ErrorCode.CUSTOMER_ACCESS_BLOCKED,com.arena.core.exception.ErrorCode.INVALID_STATE,com.arena.core.exception.ErrorCode.PAYMENT_REQUIRED,com.arena.core.exception.ErrorCode.RESOURCE_NOT_FOUND,com.arena.core.exception.ErrorCode.SERVICE_UNAVAILABLE,com.arena.core.exception.ErrorCode.SUBSCRIPTION_ACCESS_BLOCKED,com.arena.core.exception.ErrorCode.SUBSCRIPTION_EXPIRED,com.arena.core.exception.ErrorCode.USER_DISABLED})
 @PutMapping("/manager-access") public AcademyStaff managerAccess(@AuthenticationPrincipal Jwt jwt,@PathVariable Long id,@Valid @RequestBody ManagerAccess r){return login.managerAccess(jwt,id,r.accessLevel(),r.version());}
 @io.swagger.v3.oas.annotations.Operation(summary="Enable staff login and send setup email", description="Owner or FULL_OPERATIONS Manager; current academy and record version required. Managers cannot manage Owners/Managers or grant MANAGER. Login is optional and separate from personnel registration. Setup uses Keycloak VERIFY_EMAIL, UPDATE_PASSWORD and one-time ARENA_STAFF_SETUP; password/verification actions run in Keycloak, not new ArenaOps endpoints. Provision a Keycloak identity without a plaintext password and send the existing 24-hour setup email. Member must be active and NOT_ENABLED or PROVISIONING_FAILED, with no appUserId. Provisioning/mail failures can preserve membership state; refresh it before retrying. Application roles are validated server-side.")
 @com.arena.core.documentation.DocumentedErrors({com.arena.core.exception.ErrorCode.CONFLICT,com.arena.core.exception.ErrorCode.CUSTOMER_ACCESS_BLOCKED,com.arena.core.exception.ErrorCode.EMAIL_DELIVERY_FAILED,com.arena.core.exception.ErrorCode.IDENTITY_CREATION_FAILED,com.arena.core.exception.ErrorCode.IDENTITY_PROVIDER_UNAVAILABLE,com.arena.core.exception.ErrorCode.INVALID_STATE,com.arena.core.exception.ErrorCode.PAYMENT_REQUIRED,com.arena.core.exception.ErrorCode.RESOURCE_NOT_FOUND,com.arena.core.exception.ErrorCode.SERVICE_UNAVAILABLE,com.arena.core.exception.ErrorCode.SUBSCRIPTION_ACCESS_BLOCKED,com.arena.core.exception.ErrorCode.SUBSCRIPTION_EXPIRED,com.arena.core.exception.ErrorCode.DUPLICATE_USERNAME,com.arena.core.exception.ErrorCode.DUPLICATE_EMAIL,com.arena.core.exception.ErrorCode.USER_ALREADY_EXISTS,com.arena.core.exception.ErrorCode.USER_DISABLED})
 @PostMapping public AcademyStaff enable(@AuthenticationPrincipal Jwt jwt,@PathVariable Long id,@Valid @RequestBody StaffLoginService.Login r){return login.enable(jwt,id,r);}
 @io.swagger.v3.oas.annotations.Operation(summary="Resend pending staff setup email", description="Owner or FULL_OPERATIONS Manager; current academy and record version required. Managers cannot manage Owners/Managers or grant MANAGER. Login is optional and separate from personnel registration. Setup uses Keycloak VERIFY_EMAIL, UPDATE_PASSWORD and one-time ARENA_STAFF_SETUP; password/verification actions run in Keycloak, not new ArenaOps endpoints. Resend only for pending/failed invitation states permitted by the service. Uses the existing Keycloak expiry and one-time provider. Does not activate membership just because an email link was opened.")
 @com.arena.core.documentation.DocumentedErrors({com.arena.core.exception.ErrorCode.CONFLICT,com.arena.core.exception.ErrorCode.CUSTOMER_ACCESS_BLOCKED,com.arena.core.exception.ErrorCode.EMAIL_DELIVERY_FAILED,com.arena.core.exception.ErrorCode.INVALID_STATE,com.arena.core.exception.ErrorCode.PAYMENT_REQUIRED,com.arena.core.exception.ErrorCode.RESOURCE_NOT_FOUND,com.arena.core.exception.ErrorCode.SERVICE_UNAVAILABLE,com.arena.core.exception.ErrorCode.SUBSCRIPTION_ACCESS_BLOCKED,com.arena.core.exception.ErrorCode.SUBSCRIPTION_EXPIRED,com.arena.core.exception.ErrorCode.USER_DISABLED})
 @PostMapping("/resend") public AcademyStaff resend(@AuthenticationPrincipal Jwt jwt,@PathVariable Long id,@Valid @RequestBody StaffLoginService.Version r){return login.resend(jwt,id,r);}
 @io.swagger.v3.oas.annotations.Operation(summary="Disable staff login access", description="Owner or FULL_OPERATIONS Manager; current academy and record version required. Managers cannot manage Owners/Managers or grant MANAGER. Login is optional and separate from personnel registration. Setup uses Keycloak VERIFY_EMAIL, UPDATE_PASSWORD and one-time ARENA_STAFF_SETUP; password/verification actions run in Keycloak, not new ArenaOps endpoints.")
 @com.arena.core.documentation.DocumentedErrors({com.arena.core.exception.ErrorCode.CONFLICT,com.arena.core.exception.ErrorCode.CUSTOMER_ACCESS_BLOCKED,com.arena.core.exception.ErrorCode.INVALID_STATE,com.arena.core.exception.ErrorCode.PAYMENT_REQUIRED,com.arena.core.exception.ErrorCode.RESOURCE_NOT_FOUND,com.arena.core.exception.ErrorCode.SERVICE_UNAVAILABLE,com.arena.core.exception.ErrorCode.SUBSCRIPTION_ACCESS_BLOCKED,com.arena.core.exception.ErrorCode.SUBSCRIPTION_EXPIRED,com.arena.core.exception.ErrorCode.USER_DISABLED,com.arena.core.exception.ErrorCode.IDENTITY_PROVIDER_UNAVAILABLE})
 @PostMapping("/disable") public AcademyStaff disable(@AuthenticationPrincipal Jwt jwt,@PathVariable Long id,@Valid @RequestBody StaffLoginService.Version r){return login.disable(jwt,id,r);}
 @io.swagger.v3.oas.annotations.Operation(summary="Re-enable disabled staff login", description="Owner or FULL_OPERATIONS Manager; current academy and record version required. Managers cannot manage Owners/Managers or grant MANAGER. Login is optional and separate from personnel registration. Setup uses Keycloak VERIFY_EMAIL, UPDATE_PASSWORD and one-time ARENA_STAFF_SETUP; password/verification actions run in Keycloak, not new ArenaOps endpoints.")
 @com.arena.core.documentation.DocumentedErrors({com.arena.core.exception.ErrorCode.CONFLICT,com.arena.core.exception.ErrorCode.CUSTOMER_ACCESS_BLOCKED,com.arena.core.exception.ErrorCode.INVALID_STATE,com.arena.core.exception.ErrorCode.PAYMENT_REQUIRED,com.arena.core.exception.ErrorCode.RESOURCE_NOT_FOUND,com.arena.core.exception.ErrorCode.SERVICE_UNAVAILABLE,com.arena.core.exception.ErrorCode.SUBSCRIPTION_ACCESS_BLOCKED,com.arena.core.exception.ErrorCode.SUBSCRIPTION_EXPIRED,com.arena.core.exception.ErrorCode.USER_DISABLED,com.arena.core.exception.ErrorCode.IDENTITY_PROVIDER_UNAVAILABLE})
 @PostMapping("/enable") public AcademyStaff resume(@AuthenticationPrincipal Jwt jwt,@PathVariable Long id,@Valid @RequestBody StaffLoginService.Version r){return login.resume(jwt,id,r);}
 @io.swagger.v3.oas.annotations.Operation(summary="Update staff application roles (Owner only)", description="Owner-only operation; current academy and record version required. Managers cannot manage Owners/Managers or grant MANAGER. Login is optional and separate from personnel registration. Setup uses Keycloak VERIFY_EMAIL, UPDATE_PASSWORD and one-time ARENA_STAFF_SETUP; password/verification actions run in Keycloak, not new ArenaOps endpoints.")
 @com.arena.core.documentation.DocumentedErrors({com.arena.core.exception.ErrorCode.CONFLICT,com.arena.core.exception.ErrorCode.CUSTOMER_ACCESS_BLOCKED,com.arena.core.exception.ErrorCode.INVALID_STATE,com.arena.core.exception.ErrorCode.PAYMENT_REQUIRED,com.arena.core.exception.ErrorCode.RESOURCE_NOT_FOUND,com.arena.core.exception.ErrorCode.SERVICE_UNAVAILABLE,com.arena.core.exception.ErrorCode.SUBSCRIPTION_ACCESS_BLOCKED,com.arena.core.exception.ErrorCode.SUBSCRIPTION_EXPIRED,com.arena.core.exception.ErrorCode.TRAINING_DEPENDENCY_EXISTS,com.arena.core.exception.ErrorCode.USER_DISABLED})
 @PutMapping("/roles") public AcademyStaff roles(@AuthenticationPrincipal Jwt jwt,@PathVariable Long id,@Valid @RequestBody Roles r){return login.roles(jwt,id,r.roles(),r.version());}
}
